// The harness is active in production, behind the MedSpa Test Key, because the live test suites need it. It runs only the
// allow-listed tool workflows (Allow List: n8n-push.sh resolves each WFID:<name> value to the live id) and only for test
// contacts: tg:9000000NN (tool cases), tg:9000000NNN and wa:+1555000NNNN (dialogs; the ranges Normalize lets into Test
// Inbound), the ranges tests/cleanup.sh treats as test contacts. A contact_id that is not a contact at all ("", "xyz",
// "tg:1'--", 21 digits) passes: no tool resolves it to a person, and the tool cases send exactly those to test the tools.
const body = $('Webhook').first().json.body || {};
const allow = $('Allow List').first().json || {};
const id = String(body.workflow_id || '');
const name = Object.keys(allow).find((k) => typeof allow[k] === 'string' && !allow[k].startsWith('WFID:') && allow[k] === id);
if (!id || !name) throw new Error('test-harness: workflow ' + JSON.stringify(id.slice(0, 40)) + ' is not in the allow-list');
const input = body.input && typeof body.input === 'object' && !Array.isArray(body.input) ? body.input : {};
if ('contact_id' in input) {
  const c = String(input.contact_id ?? '');
  const isContact = /^(tg|wa):\+?\d{1,20}$/i.test(c.replace(/\s+/g, ''));
  const isTest = /^tg:9000000\d{2,3}$/.test(c) || /^wa:\+1555000\d{4}$/.test(c);
  if (isContact && !isTest) throw new Error('test-harness: contact_id is not a test contact (tg:9000000NN, tg:9000000NNN, wa:+1555000NNNN)');
}
return [{ json: { ...input, __workflow_id: id } }];
